  const c = new LRUCache(2);
  expect(c.get(1)).toBe(-1);
});

test('put and get basic', () => {
  const c = new LRUCache(2);
  c.put(1, 'a');
  expect(c.get(1)).toBe('a');
});

test('evicts LRU on overflow', () => {
  const c = new LRUCache(2);
  c.put(1, 'a');
  c.put(2, 'b');
  c.put(3, 'c');
  expect(c.get(1)).toBe(-1);
  expect(c.get(3)).toBe('c');
});

test('get promotes to most-recently-used', () => {
  const c = new LRUCache(2);
  c.put(1, 'a');
  c.put(2, 'b');
  c.get(1);
  c.put(3, 'c');
  expect(c.get(1)).toBe('a');
  expect(c.get(2)).toBe(-1);
});

